import React, { useEffect, useState } from "react";
import axios from "axios";
import PageHeader from "./PageHeader";
import DashboardCard from "./DashboardCard";
import SectionCard from "./SectionCard";
import AlertBox from "./AlertBox";
import { FaTasks, FaBookOpen, FaCheckCircle, FaChartLine } from "react-icons/fa";
import "./dashboard.css";

function QuizStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [quizId, setQuizId] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState(null);
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    const fetchEnrolledCourses = async () => {
      try {
        const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
        const allCourses = coursesRes.data.courses || [];

        const enrollRes = await axios.get(
          `http://127.0.0.1:8000/enrollments/${studentId}`
        );

        const enrolledIds = enrollRes.data.map((e) => e.course_id);
        const enrolledCourses = allCourses.filter((c) =>
          enrolledIds.includes(c.id)
        );

        setCourses(enrolledCourses);
      } catch (err) {
        console.error(err);
      }
    };

    fetchEnrolledCourses();
  }, [studentId]);

  useEffect(() => {
    if (!selectedCourse) return;

    axios
      .get(`http://127.0.0.1:8000/course-quiz/${selectedCourse}`)
      .then((res) => {
        setQuizId(res.data.quiz_id || null);
        setQuestions(res.data.questions || []);
        setAnswers({});
        setScore(null);
      })
      .catch((err) => console.error(err));
  }, [selectedCourse]);

  const handleChange = (qId, option) => {
    setAnswers((prev) => ({
      ...prev,
      [qId]: option
    }));
  };

  const submitQuiz = async () => {
    if (!quizId) {
      setAlert({
        message: "No quiz available for this subject",
        type: "error"
      });
      return;
    }

    try {
      const res = await axios.post("http://127.0.0.1:8000/submit-quiz", {
        quiz_id: quizId,
        student_id: parseInt(studentId),
        answers: answers
      });

      setScore(res.data.score);

      setAlert({
        message: `Quiz submitted successfully. Progress +${res.data.progress_added || 0}`,
        type: "success"
      });

      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Quiz submission failed",
        type: "error"
      });
    }
  };

  const answeredCount = Object.keys(answers).length;

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <PageHeader
        title="Student Quiz Section"
        subtitle="Choose your enrolled subject, attempt quiz, and improve your progress."
      />

      <div className="grid-4" style={{ marginBottom: "18px" }}>
        <DashboardCard
          icon={<FaBookOpen />}
          label="Enrolled Subjects"
          value={courses.length}
        />
        <DashboardCard
          icon={<FaTasks />}
          label="Quiz Loaded"
          value={quizId ? "Yes" : "No"}
        />
        <DashboardCard
          icon={<FaCheckCircle />}
          label="Answered"
          value={answeredCount}
        />
        <DashboardCard
          icon={<FaChartLine />}
          label="Score"
          value={score !== null ? score : "N/A"}
        />
      </div>

      <SectionCard title="Select Subject">
        <select
          className="select"
          value={selectedCourse}
          onChange={(e) => setSelectedCourse(e.target.value)}
        >
          <option value="">Select Enrolled Subject</option>
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title} {c.subject_code ? `(${c.subject_code})` : ""}
            </option>
          ))}
        </select>
      </SectionCard>

      {!selectedCourse ? (
        <SectionCard title="Quiz Area">
          <p>Please select a subject.</p>
        </SectionCard>
      ) : questions.length === 0 ? (
        <SectionCard title="Quiz Area">
          <p>No quiz available for this subject.</p>
        </SectionCard>
      ) : (
        <SectionCard title="Attempt Quiz">
          {questions.map((q, index) => (
            <div className="list-card" key={q.id}>
              <h4 style={{ marginTop: 0 }}>
                Q{index + 1}. {q.question}
              </h4>

              {[q.option1, q.option2, q.option3, q.option4].map((opt, i) => (
                <div
                  key={i}
                  onClick={() => handleChange(q.id, opt)}
                  style={{
                    padding: "12px",
                    margin: "8px 0",
                    borderRadius: "12px",
                    border: "1px solid #e5e7eb",
                    cursor: "pointer",
                    background: answers[q.id] === opt ? "#ede9fe" : "#fff"
                  }}
                >
                  {opt}
                </div>
              ))}
            </div>
          ))}

          <div className="btn-row">
            <button className="btn btn-primary" onClick={submitQuiz}>
              Submit Quiz
            </button>
          </div>

          {score !== null && (
            <div style={{ marginTop: "16px" }}>
              <span className="badge badge-green">
                Your Score: {score} / {questions.length}
              </span>
            </div>
          )}
        </SectionCard>
      )}
    </div>
  );
}

export default QuizStudent;
